import lvgl as lv
import zlib
import ubinascii


def _image(encoded, width, height):
    data = zlib.decompress(ubinascii.a2b_base64(encoded))
    descriptor = lv.img_dsc_t({
        "header": {"always_zero": 0, "w": width, "h": height, "cf": lv.img.CF.TRUE_COLOR_ALPHA},
        "data_size": len(data),
        "data": data,
    })
    return data, descriptor

TemporaryImage_data, TemporaryImage = _image(b"", 64, 64)
ui_img_background_png_data, ui_img_background_png = _image(b"", 800, 480)
ui_img_on_png_data, ui_img_on_png = _image(b"", 80, 79)
ui_img_off_png_data, ui_img_off_png = _image(b"", 80, 79)

# Compatibility name used by the original CrowPanel demo.
ui_img_background1_png = ui_img_background_png
